            var i: i32 = 0;
            _ = &i;
            while (i < 6) {
                const x: i32 = demo_corner_sx(demo_still(0), p, k, i);
                const y: i32 = demo_corner_sy(demo_still(0), p, k, i);
                if (!((((x >= 0) and (x <= PRESET_W[p])) and (y >= 0)) and (y <= PRESET_H[p]))) __t27_assert_fail("\n  assertion failed:\n    x = {any}\n    PRESET_W[p] = {any}\n    y = {any}\n    PRESET_H[p] = {any}\n", .{ x, PRESET_W[p], y, PRESET_H[p] });
                i = i + 1;
            }
            k = k + 1;
        }
        p = p + 1;
    }
}
